(60, 'HABLAR CON EL DOCTOR ROBLES', 'HABLAR CON EL DOCTOR ROBLES ,LA DRA. PAU TIENE UNA TAREA DEL QUÍMICO.', '2026-10-17', 1, 'general', NULL, NULL, 'cerrada', 'SE HA HABLADO CON EL DR ROBLES, SIN EMBARGO NO DIÓ UNA RESPUESTA CONCRETA, YA QUE SU RESPUESTA FUE \"TE AVISO\" EL DÍA MIÉRCOLES EL TENDRÁ PROCEDIMIENTO EN CLÍNICA, SE APROVECHARÁ EL ESPACIO PARA UNA RESPUESTA CLARA.', 'NO ACEPTÓ ESTAR COMPROMETIDO PARA TRABAJAR EN CLÍNICA EL FIN DE SEMANA. SOLO DE MANERA OCASIONAL.', NULL, NULL, '2026-10-19 10:45:30', '2026-10-22 15:31:18', '2026-10-26 09:14:09', 9, '2026-10-26 09:14:59', 9, '2026-10-29 14:05:02', NULL, NULL, 9, '2026-10-12 14:23:28', '2026-10-29 14:05:02', NULL),
(61, 'REVISION DE SU NOTA DE ALTA DEL DOCTOR CORTES Y DE TODOS LOS DOCTORES', 'GENERAR Y REVISAR LOS FORMATOS DE ALTA', '2026-10-17', 2, 'general', NULL, NULL, 'cerrada', 'YA SE INICIARON A SUBIR LAS NOTAS POR CADA USUARIO MEDICO, PRIMERO SE INICIARON A RECABAR LAS NOTAS DE CADA MEDICO, EL UNICO QUE ME LAS QUISO COMPARTIR FUE TLASECA, LOS DEMAS FUERON SACADOS DE LOS EXPEDIENTES', 'ESTA BIEN, SOLO HAY QUE FINALIZAR LAS ACTIVIDADES O BIEN TAREAS', NULL, NULL, '2026-10-24 11:29:04', '2026-10-26 09:37:29', '2026-10-29 09:44:42', 9, '2026-10-29 09:44:53', 9, '2026-10-29 13:42:48', NULL, NULL, 9, '2026-10-12 14:28:26', '2026-10-29 13:42:48', NULL),
(62, 'COORDINACIÓN DE LA TOMBOLA', 'COORDINAR LA RIFA', '2026-10-23', 1, 'general', NULL, NULL, 'cerrada', 'SE REALIZARON BOLETOS Y SE PREPARO CAJA PARA RIFA', 'TODO LISTO PARA LA RIFA..', NULL, NULL, '2026-10-21 15:53:03', '2026-10-21 15:53:21', '2026-10-22 11:42:08', 9, '2026-10-22 11:42:18', 9, '2026-10-22 11:42:27', NULL, NULL, 9, '2026-10-12 15:07:56', '2026-10-22 11:42:27', NULL),
(63, 'GENERAR PROPUESTA PARA DOPLER', 'GENERAR UNA PROPUESTA PARA LOS DOPLER', '2026-10-17', NULL, 'general', NULL, NULL, 'autorizada', 'SE MANDARON A PEDIR 2 DOPPLER MAS Y RECIPIENTES PARA COLOCAR EL GEL.. EN TEMU', 'SOLO EN ESPERA QUE LLEGUEN LOS MATERIALES', NULL, NULL, '2026-10-21 15:54:37', '2026-10-21 15:54:54', '2026-10-22 11:47:53', 9, NULL, NULL, NULL, NULL, NULL, 9, '2026-10-12 15:18:52', '2026-10-22 11:47:53', NULL),
(64, 'FARMACIA HOSPITALARIA', 'REALIZAR LAS MODIFICACIONES CORRESPONDIENTE A FARMACIA HOSPITALARIA, GENERAR LOS PNO ADECUADOS,GENERAR EL COMITÉ Y POSTERIORMENTE LA UNIDAD DE FARMACOVIGILANCIA,  REALIZAR CERTIFICACIÓN O CURSOS NECESARIOS PARA PERSONAL DE FARMACIA Y TODO LO QUE TENGA RELACIÓN A ELLO, (STOCK, FACTURACIONES O MEJORAS).', '2026-10-20', 3, 'proyecto', 2, NULL, 'en_proceso', 'SE VAN A SUBIR LOS MEDICAMENTOS A LA FARMACIA HOSPITALARIA Y SE VAN A ACOMODAR CONFORME AL CROQUIS QUE ENVIO EL INGENIERO', NULL, NULL, NULL, '2026-10-29 11:52:07', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, '2026-10-13 12:34:47', '2026-10-29 11:52:07', NULL),
(65, 'UNIDAD DE FARMACOVIGILANCIA Y TECNOVIGILANCIA', 'GENERAR EL ÁREA, LA UNIDAD Y EL COMITÉ DE FARMACOVIGILANCIA, REALIZAR LO NECESARIO PARA PODER TENERLAS UN ORDEN.', '2026-10-20', 3, 'proyecto', 3, NULL, 'asignada', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, '2026-10-13 12:42:05', '2026-10-13 12:42:05', NULL),
(66, 'PROYECTO PUBLICITARIO COPRISEM', 'GENERAR UN PLAN DE TRABAJO ANUAL PARA PRESENTAR A AL CIS, CON INTENCIÓN DE GENERAR ANUNCIOS EN TODOS LOS MODOS PUBLICITARIOS.', '2026-11-15', 2, 'proyecto', 4, NULL, 'en_proceso', 'AVANCE DE PROYECTO PUBLICITARIO', NULL, NULL, NULL, '2026-10-21 12:45:31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, '2026-10-14 10:36:58', '2026-10-21 12:45:31', NULL),
(67, 'REPORTE PARA FARMACOVIGILANCIA', 'GENERAR UN MACHOTE', '2026-10-23', 1, 'general', NULL, NULL, 'cerrada', 'HE REALIZADO EL MACHOTE PARA FARMACOVIGILANCIA', 'COMPARTO LINK DE REPORTE', NULL, NULL, '2026-10-23 11:24:54', '2026-10-23 11:42:24', '2026-10-26 09:18:52', 9, '2026-10-26 09:19:15', 9, '2026-10-26 09:19:34', NULL, NULL, 9, '2026-10-19 12:47:52', '2026-10-26 09:19:34', NULL),
(68, 'CREAR ESTRATEGIA PUBLICITARIA', 'GENERAR UNA ESTRATEGIA PUBLICITARIA PARA LAS DIFERENTES ÁREAS DE LA CLÍNICA, GENERAR ANUNCIOS FÍSICOS VISUALES Y AUDITIVOS.', '2026-10-31', 1, 'general', NULL, NULL, 'en_proceso', 'SE CREARON FLAYERS PARA COLOCAR EN ACRILICOS DENTRO DE CADA HABITACION, DEL MISMO MODO SE PEDIRAN LOS ACRILICOS EN TEMU.\r\nDEJO LA LIGA DE LOS FLAYERS', NULL, NULL, NULL, '2026-10-24 10:45:36', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, '2026-10-22 11:23:04', '2026-10-24 10:45:36', NULL),
(69, 'MUEBLE DE FARMACIA HOSPITALARIA', 'ACONDICIONARLO SIN PUERTAS NI TAPA TRASERA PARA FUNGIR COMO REPISA PARA DEVOLUCIONES DE MEDICAMENTOS', '2026-10-26', 3, 'proyecto', 2, NULL, 'asignada', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-10-26 10:41:29', '2026-10-26 10:41:29', NULL),
(70, 'PUERTA DE FARMACIA HOSPITALARIA', 'LEVANTAR PUERTA Y REAJUSTAR ALTURA YA QUE EN SU APERTURA PEGA EN EL PISO', '2026-10-26', 3, 'proyecto', 2, NULL, 'asignada', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-10-26 10:43:58', '2026-10-26 10:43:58', NULL),
(71, 'CONFIGURACION DE CAMARAS', 'CONFIGURACION DE LAS CAMARAS QUE SE INSTALARON EN FARMACIA HOSPITALARIA EN LA CUENTA QUE LES ESTAS ASIGNANDO PARA CLINICA.', '2026-10-27', 3, 'proyecto', 2, NULL, 'en_proceso', 'YA SE CONFIGURARON LAS DE URGENCIAS, RECEPCIÓN Y FARMACIA HOSPITALARIA, QUEDAN PENDIENTES LAS DE HOSPITALIZACION Y URGENCIAS', NULL, NULL, NULL, '2026-11-03 13:16:31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-10-26 10:47:39', '2026-11-03 13:16:31', NULL),
(72, 'REACOMODO Y CLASIFICACION', 'REACOMODO Y CLASIFICACION DE MEDICAMENTO Y MATERIAL EN LA NUEVA FARMACIA HOSPITALARIA, COLOCACION DE NUEVAS LETREROS SEGUN EL ACOMODO', '2026-10-26', NULL, 'proyecto', 2, NULL, 'en_proceso', 'YA SE SACO LA LISTA EN BASE A LO QUE SE ESTIPULO EN EL CROQUIS, SE LE PASO A SARA, PERO SE MANDARAN A HACER DE NUEVO, PORQUE CAMBIARON LOS CONCEPTOS.', NULL, NULL, NULL, '2026-10-29 11:54:16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-10-26 10:53:38', '2026-10-29 11:54:16', NULL),
