INSERT INTO `tipos_equipo` (`id`, `nombre`, `clave`, `descripcion`, `estado`, `created_at`, `updated_at`) VALUES
(1, 'Médico', 'medico', NULL, 'activo', '2026-09-09 17:00:04', '2026-09-09 17:00:04'),
(2, 'CÓMPUTO', 'computo', 'PERSONA CON CONOCIMIENTOS BÁSICOS DE COMPUTO, PARA REALIZAR MANTENIMIENTO PREVENTIVOS, CORRECTIVAS Y MANTENIMIENTO SISTEMATIZADOS A EQUIPOS QUE SE ENCUENTRAN DENTRO DE LAS INSTALACIONES DE CLÍNICA.', 'activo', '2026-09-09 17:00:04', '2026-10-20 11:20:12'),
(3, 'CLIMATIZACIÓN', 'climatizacion', 'INSTALAR, DIAGNOSTICAR, DAR MANTENIMIENTO PREVENTIVO Y REPARAR SISTEMAS DE CALEFACCIÓN, VENTILACIÓN, AIRE ACONDICIONADO Y REFRIGERACIÓN, GARANTIZANDO EL ÓPTIMO FUNCIONAMIENTO DE LOS EQUIPOS Y EL CONFORT TÉRMICO DE LOS ESPACIOS.', 'activo', '2026-09-09 17:00:04', '2026-10-20 11:22:47'),
(4, 'ELÉCTRICO', 'electrico', 'CONOCIMIENTO PARA INSTALAR, MANTENER, DIAGNOSTICAR Y REPARAR LOS SISTEMAS ELÉCTRICOS, CABLEADOS, TABLEROS Y EQUIPOS DE DISTRIBUCIÓN DE ENERGÍA, GARANTIZANDO EL FUNCIONAMIENTO ÓPTIMO DE LAS INSTALACIONES.', 'activo', '2026-09-09 17:00:04', '2026-10-20 11:15:53'),
(5, 'HIDRÁULICO', 'hidraulico', 'INSTALAR, DIAGNOSTICAR, DAR MANTENIMIENTO PREVENTIVO Y CORREGIR FALLAS EN LOS SISTEMAS Y COMPONENTES HIDRÁULICOS DE EQUIPOS, MAQUINARIA O VEHÍCULOS PARA ASEGURAR SU OPERACIÓN CONTINUA Y SEGURA.', 'activo', '2026-09-09 17:00:04', '2026-10-20 11:23:52'),
(6, 'Mobiliario', 'mobiliario', NULL, 'activo', '2026-09-09 17:00:04', '2026-09-09 17:00:04'),
(7, 'Transporte', 'transporte', NULL, 'activo', '2026-09-09 17:00:04', '2026-09-09 17:00:04'),
(8, 'Seguridad', 'seguridad', NULL, 'activo', '2026-09-09 17:00:04', '2026-09-09 17:00:04'),
(10, 'EQUIPO DE COMUNICACION', 'equipo_de_comunicacion', NULL, 'activo', '2026-10-16 20:35:51', '2026-10-16 20:35:51'),
(11, 'PINTURA', 'pintura', 'PREPARAR, TRATAR Y APLICAR RECUBRIMIENTOS, BARNICES Y PINTURAS EN DIFERENTES SUPERFICIES (PAREDES, ESTRUCTURAS METÁLICAS, MADERA O MAQUINARIA), GARANTIZANDO UN ACABADO DE ALTA CALIDAD Y DURABILIDAD.', 'activo', '2026-10-20 10:58:06', '2026-10-20 11:21:22'),
(12, 'HERRERÍA', 'herreria', 'FABRICAR, REPARAR, ARMAR E INSTALAR ESTRUCTURAS, PROTECCIONES, PUERTAS, VENTANAS, PORTONES Y ELEMENTOS METÁLICOS CON BASE EN MEDIDAS, PLANOS O ESPECIFICACIONES TÉCNICAS, GARANTIZANDO LA CALIDAD, FUNCIONALIDAD Y SEGURIDAD DE LOS PRODUCTOS.', 'activo', '2026-10-20 11:28:57', '2026-10-20 11:28:57'),
(13, 'PLOMERIA', 'plomeria', 'INSTALAR, MANTENER, DIAGNOSTICAR Y REPARAR SISTEMAS DE TUBERÍAS, DRENAJE, SUMINISTRO DE AGUA Y GAS, GARANTIZANDO EL CORRECTO FUNCIONAMIENTO DE LAS INSTALACIONES Y EL CUMPLIMIENTO DE LAS NORMAS DE SEGURIDAD.', 'activo', '2026-10-20 11:30:15', '2026-10-20 11:30:15'),
(14, 'CARPINTERIA', 'carpinteria', 'FABRICAR, REPARAR, ARMAR E INSTALAR MUEBLES, ESTRUCTURAS Y PIEZAS DE MADERA O TABLEROS, GARANTIZANDO LA CALIDAD, EL CUMPLIMIENTO DE MEDIDAS Y LOS ACABADOS SEGÚN LOS PLANOS O REQUERIMIENTOS DEL SERVICIO.', 'activo', '2026-10-20 11:31:52', '2026-10-20 11:31:52'),
(15, 'CONSTRUCTOR', 'constructor', 'CONOCIMIENTOS PARA ENCARGARSE DE LA CONSTRUCCIÓN, EL LEVANTAMIENTO DE MUROS, LA APLICACIÓN DE APLANADOS, LA NIVELACIÓN Y LA REPARACIÓN DE ESTRUCTURAS EN DIFERENTES PROYECTOS.', 'activo', '2026-10-20 11:34:02', '2026-10-20 11:34:02'),
(16, 'LIMPIEZA', 'limpieza', 'GARANTIZAR LA LIMPIEZA, EL ORDEN Y LA DESINFECCIÓN DE LAS INSTALACIONES, CONTRIBUYENDO A MANTENER UN ENTORNO SEGURO, SALUDABLE Y AGRADABLE PARA EMPLEADOS, CLIENTES O VISITANTES, APEGÁNDOSE A NORMAS VIGENTES.', 'activo', '2026-10-20 12:30:51', '2026-10-20 12:30:51'),
(17, 'LAVANDERIA', 'lavanderia', 'GARANTIZAR EL CORRECTO PROCESO DE RECEPCIÓN, CLASIFICACIÓN, LAVADO, SECADO, PLANCHADO Y ENTREGA DE LAS PRENDAS O TEXTILES, ASEGURANDO ALTOS ESTÁNDARES DE LIMPIEZA Y CUIDADO DE LA ROPA.', 'activo', '2026-10-20 12:32:30', '2026-10-20 12:32:30');
